<?php
require_once __DIR__ . '/../../config/response.php'; require_once __DIR__ . '/../../config/security.php'; require_once __DIR__ . '/../../services/PrivateStorage.php';
header('Cache-Control: no-store'); $pdo=Database::getInstance(); $input=$_SERVER['REQUEST_METHOD']==='POST'?getJsonInput():$_GET; $session=validateSession($pdo,getBearerToken()?:($input['token']??''),15); if(!$session['valid']||!empty($session['is_2fa_pending'])) jsonResponse(['success'=>false,'error'=>'Please sign in to continue.'],401); $uid=(int)$session['user']['id'];
$stmt=$pdo->prepare("SELECT w.uuid,w.currency_code,c.name,c.kind,c.decimals,w.available_balance,w.pending_balance,w.status,wra.provider,wra.account_name,wra.bank_name,wra.account_number_encrypted,wra.account_number_display,wra.status receiving_status FROM wallets w JOIN currencies c ON c.code=w.currency_code LEFT JOIN wallet_receiving_accounts wra ON wra.wallet_id=w.id AND wra.status IN ('provisioning','active') WHERE w.user_id=? AND w.status<>'closed' AND (c.kind='crypto' OR c.code='NGN') ORDER BY c.kind='fiat' DESC,c.code"); $stmt->execute([$uid]); $wallets=$stmt->fetchAll(); foreach($wallets as &$wallet){$wallet['account_number']=null; if(!empty($wallet['account_number_encrypted'])){try{$wallet['account_number']=PrivateStorage::decrypt($wallet['account_number_encrypted'],'wallet-account');}catch(Throwable $e){error_log('Wallet account decrypt failed: '.$e->getMessage());} } unset($wallet['account_number_encrypted']);} unset($wallet); $currencies=$pdo->query("SELECT code,name,kind,decimals,network FROM currencies WHERE is_enabled=1 AND (kind='crypto' OR code='NGN') ORDER BY kind='fiat' DESC,code")->fetchAll(); jsonResponse(['success'=>true,'wallets'=>$wallets,'currencies'=>$currencies]);
